// wf0-smoke: proves NODE_FUNCTION_ALLOW_EXTERNAL=@langchain/core,zod works
// This is the gate for E1-1 AC. If this workflow fails, the stack is misconfigured.
const { DynamicStructuredTool } = require('@langchain/core/tools');
const { z } = require('zod');

// Build a trivial tool to prove imports resolve inside the n8n process
const tool = new DynamicStructuredTool({
  name: 'smoke_echo',
  description: 'Echoes input',
  schema: z.object({ input: z.string() }),
  func: async ({ input }) => `echo:${input}`,
});

const result = await tool.invoke({ input: 'hello' });
return [{ json: { smoke: 'pass', tool_result: result, langchain: !!DynamicStructuredTool, zod: !!z } }];

